int trap(const vector<int>& h) {
    int l = 0, r = (int)h.size() - 1;
    int leftMax = 0, rightMax = 0, water = 0;
    while (l < r) {
        if (h[l] < h[r]) {
            // left is the smaller side, so leftMax alone bounds the water here
            leftMax = max(leftMax, h[l]);
            water += leftMax - h[l];
            ++l;
        } else {
            rightMax = max(rightMax, h[r]);
            water += rightMax - h[r];
            --r;
        }
    }
    return water;
}

void nextPermutation(vector<int>& a) {
    int n = (int)a.size(), i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) --i;      // suffix from i+1 is non-increasing
    if (i >= 0) {
        int j = n - 1;
        while (a[j] <= a[i]) --j;                // rightmost element strictly greater
        swap(a[i], a[j]);
    }
    reverse(a.begin() + i + 1, a.end());         // suffix becomes ascending = smallest
}

