def next_permutation(a: list[int]) -> None:
    n = len(a)
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1                       # suffix from i+1 is non-increasing
    if i >= 0:
        j = n - 1
        while a[j] <= a[i]:
            j -= 1                   # rightmost element strictly greater
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])  # suffix becomes ascending = smallest

