int maxProduct(const vector<int>& a) {
    int curMax = a[0], curMin = a[0], best = a[0];
    for (size_t i = 1; i < a.size(); ++i) {
        int x = a[i];
        int cand1 = curMax * x, cand2 = curMin * x;
        curMax = max(x, max(cand1, cand2));   // a negative x makes the old MIN the new MAX
        curMin = min(x, min(cand1, cand2));
        best = max(best, curMax);
    }
    return best;
}

void rotate(vector<vector<int>>& m) {
    int n = (int)m.size();
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)   // j > i only, or you swap back
            swap(m[i][j], m[j][i]);
    for (auto& row : m)
        reverse(row.begin(), row.end());
}

