def spiral_order(m: list[list[int]]) -> list[int]:
    if not m:
        return []
    out = []
    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            out.append(m[top][j])
        top += 1
        for i in range(top, bottom + 1):
            out.append(m[i][right])
        right -= 1
        if top <= bottom:                    # guard: single remaining row
            for j in range(right, left - 1, -1):
                out.append(m[bottom][j])
            bottom -= 1
        if left <= right:                    # guard: single remaining column
            for i in range(bottom, top - 1, -1):
                out.append(m[i][left])
            left += 1
    return out

