vector<int> productExceptSelf(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, 1);
    for (int i = 1; i < n; ++i)
        out[i] = out[i - 1] * a[i - 1];   // out holds left-products only
    int right = 1;                        // single scalar carries the right side
    for (int i = n - 1; i >= 0; --i) {
        out[i] *= right;
        right *= a[i];
    }
    return out;
}

