def product_except_self(a: list[int]) -> list[int]:
    n = len(a)
    out = [1] * n
    for i in range(1, n):
        out[i] = out[i - 1] * a[i - 1]   # out holds left-products only
    right = 1                            # single scalar carries the right side
    for i in range(n - 1, -1, -1):
        out[i] *= right
        right *= a[i]
    return out
